contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public {
        require(from != address(0), "from is zero");
        require(to != address(0), "to is zero");
        require(from != address(c), "from is c");
        require(to != address(c), "to is c");
        require(to != from, "same address");

        uint256 supplyBefore = c.totalSupply();
        uint256 fromBalBefore = c.balanceOf(from);
        uint256 toBalBefore = c.balanceOf(to);
        uint256 allowedBefore = c.allowance(from, msg.sender);

        c.approve(to, amount);
        bool success = c.transferFrom(from, to, amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 fromBalAfter = c.balanceOf(from);
        uint256 toBalAfter = c.balanceOf(to);

        assert(success
            ? (fromBalAfter == fromBalBefore - amount
            && toBalAfter == toBalBefore + amount
            && supplyAfter == supplyBefore)
            : (fromBalAfter == fromBalBefore
            && toBalAfter == toBalBefore
            && supplyAfter == supplyBefore));
    }
}

